// app-power.js — page module extracted from app.js (buildless, classic script;
// all symbols remain global like the rest of the client JS).
// Generated by refactor extraction. Do not add a build step.

// v6.4.2: per-sensor ignore controls (Lucide-style strokes, matching the rest
// of the chrome — never an emoji).
const _THERMAL_ICON = {
  ignore:  '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 10 8 10 8a18.5 18.5 0 0 1-2.16 3.19M6.61 6.61A18.45 18.45 0 0 0 2 12s3 8 10 8a9.12 9.12 0 0 0 5.39-1.61"/><line x1="2" y1="2" x2="22" y2="22"/></svg>',
  restore: '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>',
};

// Ignore / restore a single board sensor. A dead or unconnected pin (the
// classic nct67xx AUXTIN case) otherwise becomes the host's hottest sensor and
// from there drives the page headline, temp_high, and the overheating risk
// factor. The list is per device and rides the metric-thresholds endpoint.
async function thermalIgnoreSensor(devArg, label) { return _thermalSetIgnore(devArg, label, true); }
async function thermalUnignoreSensor(devArg, label) { return _thermalSetIgnore(devArg, label, false); }

async function _thermalSetIgnore(devArg, label, ignore) {
  // The data-action dispatcher coerces a numeric-looking arg to Number; both
  // a device id and a sensor label must survive as strings.
  const devId = String(devArg);
  const lbl = String(label == null ? '' : label);
  if (!lbl) return;
  const cur = await api('GET', `/devices/${encodeURIComponent(devId)}/metric-thresholds`);
  // api() RESOLVES on 4xx rather than throwing — detect the refusal on the body.
  if (!cur || cur.error) { toast(cur?.error || 'Could not read this device’s sensor settings', 'error'); return; }
  const set = new Set(Array.isArray(cur.sensor_ignores) ? cur.sensor_ignores.map(String) : []);
  if (ignore) set.add(lbl); else set.delete(lbl);
  const r = await api('PATCH', `/devices/${encodeURIComponent(devId)}/metric-thresholds`,
                      { sensor_ignores: Array.from(set) });
  if (!r || r.error) { toast(r?.error || 'Could not update the sensor list', 'error'); return; }
  toast(ignore ? `Ignoring ${lbl} — it no longer counts toward this host’s temperature`
               : `Counting ${lbl} again`, 'success');
  // The ignore changes which sensor is hottest, so the whole roll-up moves.
  _thermalRollups.clear();
  await loadThermal();
}

async function loadThermal() {
  const tbody = document.getElementById('thermal-tbody');
  const summary = document.getElementById('thermal-summary');
  if (!tbody) return;
  tableCtl.wireSortOnly('thermal-thead', 'thermal', () => _renderThermal());
  tbody.innerHTML = _skeletonRows(5);
  // Refresh means refresh: drop the per-tier roll-up cache so an expanded
  // host's timeline re-fetches instead of redrawing the snapshot it opened on.
  _thermalRollups.clear();
  try {
    const data = await api('GET', '/fleet/thermal');
    _thermalResp = data;
    if (summary) summary.textContent = `${data.count} host${data.count === 1 ? '' : 's'} · ${data.hot} hot`;
    _renderThermal();
  } catch (e) {
    _errorState(tbody, loadThermal, {msg: `Failed to load: ${String(e)}`, colspan: 9});
  }
}

function toggleThermalDetail(id) {
  if (_thermalExpanded.has(id)) _thermalExpanded.delete(id); else _thermalExpanded.add(id);
  _renderThermal();
}

function _renderThermal() {
  const tbody = document.getElementById('thermal-tbody');
  if (!tbody || !_thermalResp) return;
  // Server returns hosts hottest-first; sortRows preserves that until a column
  // header is clicked.
  let rows = (_thermalResp.hosts || []).slice();
  rows = tableCtl.sortRows('thermal', rows, (r) => ({
    device:       (r.device || '').toLowerCase(),
    max_temp:     r.max_temp || 0,
    sensor_label: (r.sensor_label || '').toLowerCase(),
    sensor_type:  r.sensor_type || '',
    crit_c:       (typeof r.crit_c === 'number') ? r.crit_c : 9999,
    headroom:     (typeof r.headroom === 'number') ? r.headroom : 9999,
    sensors:      r.sensors || 0,
  }));
  if (rows.length === 0) {
    tbody.innerHTML = '<tr><td colspan="9" class="isl-534">No temperature sensors reported across the fleet. Hosts report CPU / disk temps via the agent hardware inventory.</td></tr>';
    return;
  }
  const { rows: shown, note } = _capFleetRows(rows, 9, 'hosts');
  tbody.innerHTML = shown.map(r => {
    const cls = r.critical ? 'c-red fw-600' : r.hot ? 'c-amber fw-600' : '';
    const t = (typeof r.max_temp === 'number') ? fmtTemp(r.max_temp) : '—';
    const thr = (typeof r.crit_c === 'number') ? fmtTemp(r.crit_c, 0) : '<span class="c-muted">—</span>';
    let head = '<span class="c-muted">—</span>';
    if (typeof r.headroom === 'number') {
      const hc = r.headroom <= 5 ? 'c-red fw-600' : r.headroom <= 15 ? 'c-amber' : 'c-green';
      head = `<span class="${hc}">${fmtTempDelta(r.headroom)}</span>`;
    }
    let lbl = escHtml(r.sensor_label || '—');
    if (r.gpu) {  // GPU is the hottest sensor — show its fan/util/power
      const bits = [];
      if (typeof r.gpu.util_pct === 'number') bits.push(`${r.gpu.util_pct}% util`);
      if (typeof r.gpu.fan_pct === 'number') bits.push(`${r.gpu.fan_pct}% fan`);
      if (typeof r.gpu.power_w === 'number') bits.push(`${r.gpu.power_w}W`);
      if (bits.length) lbl += ` <span class="hint">· ${escHtml(bits.join(' · '))}</span>`;
    }
    // Trend sparkline — hottest reading over ~4h; coloured by current state.
    const sparkColor = r.critical ? 'var(--red)' : r.hot ? 'var(--amber)' : 'var(--green)';
    const spark = (Array.isArray(r.trend) && r.trend.length >= 2)
      ? renderSparkline(r.trend, {width: 110, height: 20, color: sparkColor, fill: true})
      : '<span class="c-muted">—</span>';
    const open = _thermalExpanded.has(r.device_id);
    const caret = `<button class="btn-icon thermal-expand" data-action="toggleThermalDetail" data-arg="${escAttr(r.device_id)}" aria-expanded="${open ? 'true' : 'false'}" title="${open ? 'Hide' : 'Show'} every sensor and the temperature timeline"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" class="${open ? 'rot-180' : ''}"><polyline points="6 9 12 15 18 9"/></svg> ${r.sensors || 0}</button>`;
    const main = `<tr>
      <td class="fw-500">${escHtml(r.device)}</td>
      <td class="${cls}">${t}</td>
      <td>${lbl}</td>
      <td class="hint">${escHtml(r.sensor_type || '—')}</td>
      <td class="hint">${thr}</td>
      <td>${head}</td>
      <td>${spark}</td>
      <td class="hint">${caret}</td>
      <td class="nowrap"><button class="btn-icon" data-action="openMetricThresholds" data-arg="${escAttr(r.device_id)}" data-arg2="${escAttr(r.device)}" title="Set warning / critical temperature thresholds">Thresholds</button></td>
    </tr>`;
    if (!open) return main;
    // Expanded: every sensor on the host, hottest-first. Capped + scrolled so a
    // host with many sensors never blows past the box.
    // The ignore/restore controls PATCH an admin-gated endpoint; showing them
    // to a read-only role would only produce a 403 toast.
    const canIgnore = !!(typeof _meCache !== 'undefined' && _meCache && _meCache.admin);
    const sensorRows = (r.detail || []).map(s => {
      // An ignored sensor stays listed (greyed) — it is the only place to
      // un-ignore it. `suspect` is the server's advisory "this reads past its
      // own critical limit while the host is plainly fine" flag.
      const sc = s.ignored ? 'c-muted'
        : (typeof s.crit === 'number' && typeof s.temp === 'number')
          ? (s.temp >= s.crit ? 'c-red fw-600' : (s.crit - s.temp) <= 10 ? 'c-amber' : '')
          : '';
      const state = s.ignored
        ? '<span class="hint">Ignored</span>'
        : s.suspect
          ? `<span class="c-amber fw-500" title="Reads at or above the sensor's own critical limit while the host is up and healthy — usually an unconnected board pin, not a real temperature">Implausible</span>`
          : '';
      const act = s.ignored
        ? `<button class="btn-icon btn-xs" data-action="thermalUnignoreSensor" data-arg="${escAttr(r.device_id)}" data-arg2="${escAttr(s.label || '')}" title="Count this sensor again">${_THERMAL_ICON.restore} Restore</button>`
        : `<button class="btn-icon btn-xs" data-action="thermalIgnoreSensor" data-arg="${escAttr(r.device_id)}" data-arg2="${escAttr(s.label || '')}" title="Stop counting this sensor — it will not set the host temperature, fire temp_high, or affect the risk score">${_THERMAL_ICON.ignore} Ignore</button>`;
      return `<tr>
        <td class="${s.ignored ? 'c-muted' : ''}">${escHtml(s.label || 'sensor')}</td>
        <td class="${sc}">${(typeof s.temp === 'number') ? fmtTemp(s.temp) : '—'}</td>
        <td class="hint">${escHtml(s.type || '—')}</td>
        <td class="hint">${(typeof s.crit === 'number') ? fmtTemp(s.crit, 0) : '—'}</td>
        <td>${state}</td>
        <td class="nowrap">${(canIgnore && s.type === 'sensor') ? act : ''}</td>
      </tr>`;
    }).join('');
    const detail = `<tr class="thermal-detail-row"><td colspan="9">
      ${_thermalTimelineBlock(r.device_id)}
      <div class="scrollable-table-wrap audit-scroll">
        <table class="data-table w-full thermal-sensor-table">
          <thead><tr><th>Sensor</th><th>Temp</th><th>Type</th><th>Critical</th><th>State</th><th>Action</th></tr></thead>
          <tbody>${sensorRows || '<tr><td colspan="6" class="hint">No per-sensor detail.</td></tr>'}</tbody>
        </table>
      </div>
    </td></tr>`;
    return main + detail;
  }).join('') + note;
  // The tbody is rebuilt wholesale on every render (sort, expand, refresh), so
  // any chart inside an expanded row is destroyed with it — repaint them here
  // rather than only where the row is first opened.
  _thermalPaintCharts();
}

// ─── Thermal timeline — the expanded row's real chart ────────────────────────
// The collapsed row keeps its 110x20 sparkline: that is the at-a-glance read and
// dropping it would be a regression. Expanding a host now also draws the thing
// the page never had — an axis chart of that host's hottest-sensor temperature
// over time, with a range picker and time-pinpointing (`zoom`), fed by the
// server roll-up tiers (same shape as the Trends page's metrics roll-up).
//
// THREE server tiers back FOUR operator-facing ranges. The 5-minute tier is
// retained ~8 days, so "24 hours" is that same tier clipped to the last day —
// full 5-minute resolution, which is the resolution an incident needs. Labels
// are the window an operator thinks in, not the bucket size they never chose.
const _THERMAL_RANGES = [
  { key: '24h', label: '24 hours', tier: 'fivemin', span: 86400 },
  { key: '8d',  label: '8 days',   tier: 'fivemin', span: 8 * 86400 },
  { key: '30d', label: '30 days',  tier: 'hourly',  span: 30 * 86400 },
  { key: '2y',  label: '2 years',  tier: 'daily',   span: 730 * 86400 },
];
const _thermalRange = new Map();     // device_id -> range key (default '24h')
const _thermalRollups = new Map();   // 'device_id|tier' -> points[] (cache)
const _thermalRollupBusy = new Set();  // 'device_id|tier' currently in flight
// A full 8-day 5-minute tier is ~2300 buckets; drawn as three series that is
// ~7k SVG nodes inside a table row. Fold to at most this many buckets first —
// min/max are folded as min/max (the envelope stays honest), avg as the mean.
const _THERMAL_MAX_POINTS = 300;

function _thermalRangeDef(key) {
  return _THERMAL_RANGES.find(r => r.key === key) || _THERMAL_RANGES[0];
}
function _thermalRangeFor(devId) {
  return _thermalRangeDef(_thermalRange.get(devId));
}
function _thermalHostName(devId) {
  const h = ((_thermalResp && _thermalResp.hosts) || []).find(x => x.device_id === devId);
  return (h && h.device) || devId;
}

// Range picker + chart slot + caption. `thermal-tl-` wraps the lot so switching
// range can repaint just this block instead of re-rendering (and scroll-jumping)
// the whole fleet table.
function _thermalTimelineBlock(devId) {
  return `<div id="thermal-tl-${escAttr(devId)}" class="mb-8">${_thermalTimelineInner(devId)}</div>`;
}
function _thermalTimelineInner(devId) {
  const cur = _thermalRangeFor(devId).key;
  // data-arg carries a 'th-' prefix so the dispatcher's numeric coercion
  // (`!isNaN(v) ? Number(v) : v`) can never mangle a device id into a number.
  const picker = '<div class="metric-range-picker">' + _THERMAL_RANGES.map(r =>
    `<button class="metric-range-btn${r.key === cur ? ' sel' : ''}" data-action="thermalSetRange"`
    + ` data-arg="th-${escAttr(devId)}" data-arg2="${r.key}"`
    + ` aria-pressed="${r.key === cur ? 'true' : 'false'}">${escHtml(r.label)}</button>`).join('')
    + '</div>';
  return picker
    + `<div id="thermal-ts-${escAttr(devId)}" class="trend-chart"></div>`
    + `<div id="thermal-tsnote-${escAttr(devId)}" class="hint mt-8"></div>`;
}

function thermalSetRange(devArg, key) {
  const devId = String(devArg).replace(/^th-/, '');
  _thermalRange.set(devId, _thermalRangeDef(key).key);
  const block = document.getElementById('thermal-tl-' + devId);
  if (!block) return;
  block.innerHTML = _thermalTimelineInner(devId);
  _thermalLoadChart(devId);
}

function _thermalPaintCharts() {
  _thermalExpanded.forEach(devId => _thermalLoadChart(devId));
}

function _thermalNote(devId, html) {
  const el = document.getElementById('thermal-tsnote-' + devId);
  if (el) el.innerHTML = html;
}

async function _thermalLoadChart(devId) {
  const el = document.getElementById('thermal-ts-' + devId);
  if (!el) return;   // row collapsed / past the fleet row cap — nothing to paint
  const def = _thermalRangeFor(devId);
  const ck = devId + '|' + def.tier;
  if (_thermalRollups.has(ck)) { _thermalDrawChart(devId); return; }
  el.innerHTML = '<div class="c-muted">Loading temperature history…</div>';
  if (_thermalRollupBusy.has(ck)) return;   // a re-render mid-fetch: let it land
  _thermalRollupBusy.add(ck);
  let points = null, err = '';
  try {
    // api() does NOT throw on an HTTP error — it resolves with the parsed error
    // body (or null on a non-JSON 502). Treating "no points key" as "no data
    // yet" would render the pre-history empty state on a 500, i.e. a UI that
    // lies about a failure. Only an actual points array counts as data.
    const r = await api('GET', `/devices/${encodeURIComponent(devId)}/thermal/rollup?tier=${def.tier}`);
    if (r && Array.isArray(r.points)) points = r.points;
    else err = (r && r.error) ? String(r.error) : 'the server returned no roll-up points';
  } catch (e) {
    err = String(e);
  } finally {
    _thermalRollupBusy.delete(ck);
  }
  if (points === null) {
    _errorState('thermal-ts-' + devId, () => _thermalLoadChart(devId),
                { msg: `Failed to load temperature history: ${err}` });
    _thermalNote(devId, '');
    return;
  }
  _thermalRollups.set(ck, points);
  // The operator can switch range mid-flight; the newer request owns the chart.
  // Without this the slower response repaints with the OTHER tier selected.
  if (_thermalRangeFor(devId).tier !== def.tier) return;
  _thermalDrawChart(devId);
}

// Fold consecutive buckets down to <= cap, preserving the min/max envelope.
function _thermalFold(pts, cap) {
  if (pts.length <= cap) return { pts, folded: 0 };
  const group = Math.ceil(pts.length / cap);
  const out = [];
  for (let i = 0; i < pts.length; i += group) {
    let mn = Infinity, mx = -Infinity, sum = 0, n = 0;
    for (const p of pts.slice(i, i + group)) {
      const t = p.temp || {};
      if (typeof t.min === 'number') mn = Math.min(mn, t.min);
      if (typeof t.max === 'number') mx = Math.max(mx, t.max);
      if (typeof t.avg === 'number') { sum += t.avg; n++; }
    }
    out.push({
      ts: pts[i].ts,
      temp: {
        min: isFinite(mn) ? mn : null,
        avg: n ? sum / n : null,
        max: isFinite(mx) ? mx : null,
      },
    });
  }
  return { pts: out, folded: group };
}

// min / avg / max across the plotted buckets, optionally clipped to a
// pinpointed [from, to] window. Values stay CELSIUS — fmtTemp does the °F.
function _thermalStats(pts, from, to) {
  let mn = Infinity, mx = -Infinity, sum = 0, n = 0, first = null, last = null;
  for (const p of pts) {
    if (from != null && p.ts < from) continue;
    if (to != null && p.ts > to) continue;
    const t = p.temp || {};
    if (first === null) first = p.ts;
    last = p.ts;
    if (typeof t.min === 'number') mn = Math.min(mn, t.min);
    if (typeof t.max === 'number') mx = Math.max(mx, t.max);
    if (typeof t.avg === 'number') { sum += t.avg; n++; }
  }
  return {
    n, first, last,
    min: isFinite(mn) ? mn : null,
    max: isFinite(mx) ? mx : null,
    avg: n ? sum / n : null,
  };
}

// _fmtTs drops to a bare clock at or below a 24h span, but BOTH ends of a
// 24-hour timeline sit on different days — "14.15 → 14.10" reads backwards.
// Floor the format span just past a day so a short window keeps its date.
function _thermalFmtTs(ts, span) { return _fmtTs(ts, Math.max(span, 86401)); }

function _thermalNoteText(def, pts, folded, from, to) {
  const st = _thermalStats(pts, from, to);
  if (!st.n) return '<span class="c-muted">No samples in the pinpointed window.</span>';
  const span = Math.max(1, st.last - st.first);
  const win = (from != null || to != null)
    ? `Pinpointed ${escHtml(_thermalFmtTs(st.first, span))} → ${escHtml(_thermalFmtTs(st.last, span))}`
    : `${escHtml(def.label)} · ${escHtml(_thermalFmtTs(st.first, span))} → ${escHtml(_thermalFmtTs(st.last, span))}`;
  const bits = [win,
                `min ${fmtTemp(st.min)}`, `avg ${fmtTemp(st.avg)}`, `max ${fmtTemp(st.max)}`];
  let extra = '';
  // Pre-history: the tier is retained far longer than this host has been
  // rolled up. Say so rather than let a short line read as "that's all there is".
  if (from == null && to == null && span < def.span * 0.6) {
    extra += `<div>Roll-up history starts ${escHtml(_thermalFmtTs(st.first, span))} — the`
           + ` ${escHtml(def.label)} view fills in as more roll-ups accumulate.</div>`;
  }
  if (folded > 1) {
    extra += `<div>Averaged ${folded} buckets per point to keep the chart readable;`
           + ` the min/max band still shows the true extremes.</div>`;
  }
  return `<div>${bits.join(' · ')}</div>` + extra;
}

// The chart needs NUMBERS on its y-axis, not fmtTemp's formatted string — but a
// second copy of the C→F conversion (and of the unit symbol) would drift from
// the formatter and ignore `ui_prefs.temp_unit`. Derive both FROM fmtTemp: two
// known points give the affine scale, and the tail of a formatted zero gives the
// symbol. One source of truth, and no unit literal in a render path
// (tests/test_v612_ux::TestTemperatureUnit pins that).
function _thermalTempAxis() {
  const zero = parseFloat(fmtTemp(0, 4));
  const hundred = parseFloat(fmtTemp(100, 4));
  const scale = (hundred - zero) / 100;
  return {
    conv: c => zero + c * scale,
    unit: fmtTemp(0, 0).replace(/^[-+\d.]+/, ''),
  };
}

function _thermalDrawChart(devId) {
  const elId = 'thermal-ts-' + devId;
  const el = document.getElementById(elId);
  if (!el) return;
  const def = _thermalRangeFor(devId);
  const ck = devId + '|' + def.tier;
  if (!_thermalRollups.has(ck)) return;   // still loading — keep the placeholder
  const raw = _thermalRollups.get(ck) || [];
  let pts = raw.filter(p => p && typeof p.ts === 'number'
                            && p.temp && typeof p.temp.avg === 'number')
               .sort((a, b) => a.ts - b.ts);
  if (!pts.length) {
    // Honest empty state: nothing has been folded yet, and the operator is told
    // what fills it and what the row's sparkline is showing in the meantime.
    el.innerHTML = '<div class="empty-state">No roll-up data yet for this host —'
      + ' the timeline folds once an hour of temperature samples exists.'
      + ' The sparkline in the row above comes from the live ~24h sample window'
      + ' and fills in first.</div>';
    _thermalNote(devId, '');
    return;
  }
  if (def.key === '24h') {
    // "24 hours" is the 5-minute tier clipped to the last day (see _THERMAL_RANGES).
    const cut = Math.floor(Date.now() / 1000) - def.span;
    const recent = pts.filter(p => p.ts >= cut);
    if (!recent.length) {
      const lastTs = pts[pts.length - 1].ts;
      el.innerHTML = '<div class="empty-state">No temperature samples in the last 24 hours'
        + ` — this host last rolled up ${escHtml(_thermalFmtTs(lastTs, def.span))}.`
        + ' Pick a longer range to see the history it does have.</div>';
      _thermalNote(devId, '');
      return;
    }
    pts = recent;
  }
  const { pts: shown, folded } = _thermalFold(pts, _THERMAL_MAX_POINTS);
  const axis = _thermalTempAxis();
  const series = [['Min', 'min'], ['Avg', 'avg'], ['Max', 'max']].map(([name, key]) => ({
    name,
    points: shown.filter(p => typeof p.temp[key] === 'number')
                 .map(p => ({ x: p.ts, y: axis.conv(p.temp[key]) })),
  })).filter(s => s.points.length);
  renderTimeSeries(elId, series, {
    yUnit: axis.unit,
    label: `${_thermalHostName(devId)} temperature — ${def.label}`,
    // Shared-chart contract: opt in to time-pinpointing, and mirror the picked
    // window into the caption below (null,null on reset).
    zoom: true,
    onZoom: (from, to) => _thermalNote(devId, _thermalNoteText(def, shown, folded, from, to)),
  });
  _thermalNote(devId, _thermalNoteText(def, shown, folded, null, null));
}

async function loadPower() {
  const tbody = document.getElementById('power-tbody');
  if (!tbody) return;
  tableCtl.wireSortOnly('power-thead', 'power', () => _renderPower());
  tbody.innerHTML = _skeletonRows(6);
  // restore the saved cost/kWh
  try {
    const saved = localStorage.getItem('rp_cost_kwh');
    const inp = document.getElementById('power-cost-kwh');
    if (saved && inp) inp.value = saved;
  } catch (_) {}
  try {
    _powerResp = await api('GET', '/fleet/power');
    _renderPower();
  } catch (e) {
    _errorState(tbody, loadPower, {msg: `Failed to load: ${String(e)}`, colspan: 6});
  }
  loadChargeback();   // v3.14.0 (#41): cost allocation card
}

function renderPowerCost() {
  try { localStorage.setItem('rp_cost_kwh', String(_costKwh())); } catch (_) {}
  _renderPowerSummary();
  _renderChargeback();
}

function _renderPowerSummary() {
  const el = document.getElementById('power-summary');
  if (!el || !_powerResp) return;
  const w = _powerResp.total_watts || 0;
  const perDay = (w / 1000) * 24 * _costKwh();
  const ob = _powerResp.on_battery || 0;
  el.textContent = `${_powerResp.count} host${_powerResp.count === 1 ? '' : 's'} · ${w} W`
    + (w ? ` · ~${(perDay).toFixed(2)}/day · ~${(perDay * 30).toFixed(0)}/mo` : '')
    + (ob ? ` · ${ob} on battery` : '');
}

function _renderPower() {
  const tbody = document.getElementById('power-tbody');
  if (!tbody || !_powerResp) return;
  _renderPowerSummary();
  let rows = (_powerResp.hosts || []).slice();
  rows = tableCtl.sortRows('power', rows, (r) => ({
    device: (r.device || '').toLowerCase(),
    status: r.status || '',
    battery_pct: r.battery_pct || 0,
    load_pct: r.load_pct || 0,
    runtime_s: r.runtime_s || 0,
    watts: r.watts || 0,
  }));
  if (rows.length === 0) {
    tbody.innerHTML = '<tr><td colspan="6" class="isl-534">No UPS or power data reported. Hosts report UPS status via NUT (upsc) or apcupsd; GPU power also counts.</td></tr>';
    return;
  }
  const { rows: shown, note } = _capFleetRows(rows, 6, 'hosts');
  tbody.innerHTML = shown.map(r => {
    const rt = (typeof r.runtime_s === 'number' && r.runtime_s) ? `${Math.round(r.runtime_s / 60)} min` : '—';
    const statusCell = r.ups
      ? `<span class="${r.on_battery ? 'c-red fw-600' : 'c-green'}">${escHtml(r.status || '—')}</span>`
      : '<span class="hint">no UPS</span>';
    const wattsCell = r.watts != null
      ? `${r.watts} W${r.watts_source === 'gpu' ? ' <span class="hint">(GPU)</span>' : ''}`
      : '—';
    return `<tr>
      <td class="fw-500">${escHtml(r.device)}</td>
      <td>${statusCell}</td>
      <td class="ta-center ${(r.battery_pct != null && r.battery_pct < 50) ? 'c-amber' : ''}">${r.battery_pct != null ? r.battery_pct + '%' : '—'}</td>
      <td class="ta-center">${r.load_pct != null ? r.load_pct + '%' : '—'}</td>
      <td class="ta-center">${rt}</td>
      <td class="ta-center">${wattsCell}</td>
    </tr>`;
  }).join('') + note;
}

async function loadDiskHealth() {
  const tbody = document.getElementById('disk-health-tbody');
  const summary = document.getElementById('disk-health-summary');
  if (!tbody) return;
  tableCtl.wireSortOnly('disk-health-thead', 'diskhealth', () => _renderDiskHealth());
  tableCtl.wireSortOnly('unstable-thead', 'unstablehosts', () => _renderUnstableHosts());
  // v6.2.0: eager wire-up — BEFORE the fetch, so the sort indicators exist even
  // while the data is still loading (the repo's sortable-table rule).
  tableCtl.wireSortOnly('reliability-thead', 'reliability', () => _renderReliability());
  tbody.innerHTML = _skeletonRows(6);
  try {
    _diskHealthResp = await api('GET', '/fleet/disk-health');
    if (summary) summary.innerHTML = `${_diskHealthResp.count} disk(s) at risk · <span class="${_diskHealthResp.critical > 0 ? 'c-red fw-600' : ''}">${_diskHealthResp.critical}</span> critical · <span class="${_diskHealthResp.high > 0 ? 'c-amber' : ''}">${_diskHealthResp.high}</span> high · ${_diskHealthResp.unstable_count || 0} unstable host(s)`;
    _renderDiskHealth();
  } catch (e) {
    _errorState(tbody, loadDiskHealth, {msg: `Failed to load: ${String(e)}`, colspan: 6});
  }
  // v6.2.0: the composite failure-likelihood table. Loaded separately so a
  // failure here can never blank the disk table above it.
  try {
    _reliabilityResp = await api('GET', '/reliability');
    _renderReliability();
  } catch (e) {
    const rb = document.getElementById('reliability-tbody');
    if (rb) rb.innerHTML = `<tr><td colspan="3" class="hint">Failed to load: ${escHtml(String(e))}</td></tr>`;
  }
}

// v6.2.0: per-host failure likelihood (0-100, higher = more likely to fail).
let _reliabilityResp = null;

function _renderReliability() {
  const tbody = document.getElementById('reliability-tbody');
  const sub = document.getElementById('reliability-sub');
  if (!tbody) return;
  const rows = (_reliabilityResp?.devices || []).filter(r => r.score > 0);
  if (sub) {
    const c = _reliabilityResp?.counts || {};
    sub.textContent = rows.length
      ? `${c.critical || 0} critical · ${c.high || 0} high · ${c.medium || 0} medium`
      : '';
  }
  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="3" class="hint">No host is showing failure signals.</td></tr>`;
    return;
  }
  const sorted = tableCtl.sortRows('reliability', rows, r => ({
    score: r.score,
    device: r.name,
    signals: (r.factors || []).length,
  }));
  const color = lvl => lvl === 'critical' ? 'c-red' : lvl === 'high' ? 'c-amber' : 'c-muted';
  tbody.innerHTML = sorted.map(r => {
    // Show every factor: the score alone is a number nobody can act on — the
    // point of the feature is WHY the host is expected to fail.
    const why = (r.factors || []).map(f =>
      `<div class="fs-11"><span class="c-muted">+${f.points}</span> ${escHtml(f.detail)}</div>`
    ).join('') || '<span class="c-muted">—</span>';
    return `<tr>
      <td class="fw-600 ${color(r.level)}">${r.score}</td>
      <td class="fw-500">${escHtml(r.name)}</td>
      <td>${why}</td>
    </tr>`;
  }).join('');
}
